head.b:skin:
/*! normalize.css v3.0.1 | MIT License | git.io/normalize */html{font-family:sans-serif;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%}body{margin:0}article,aside,details,figcaption,figure,footer,header,hgroup,main,nav,section,summary{display:block}audio,canvas,progress,video{display:inline-block;vertical-align:baseline}audio:not([controls]){display:none;height:0}[hidden],template{display:none}a{background:transparent}a:active,a:hover{outline:0}abbr[title]{border-bottom:1px dotted}b,strong{font-weight:bold}dfn{font-style:italic}h1{font-size:2em;margin:.67em 0}mark{background:#ff0;color:#000}small{font-size:80%}sub,sup{font-size:75%;line-height:0;position:relative;vertical-align:baseline}sup{top:-0.5em}sub{bottom:-0.25em}img{border:0}svg:not(:root){overflow:hidden}figure{margin:1em 40px}hr{-moz-box-sizing:content-box;box-sizing:content-box;height:0}pre{overflow:auto}code,kbd,pre,samp{font-family:monospace,monospace;font-size:1em}button,input,optgroup,select,textarea{color:inherit;font:inherit;margin:0}button{overflow:visible}button,select{text-transform:none}button,html input[type="button"],input[type="reset"],input[type="submit"]{-webkit-appearance:button;cursor:pointer}button[disabled],html input[disabled]{cursor:default}button::-moz-focus-inner,input::-moz-focus-inner{border:0;padding:0}input{line-height:normal}input[type="checkbox"],input[type="radio"]{box-sizing:border-box;padding:0}input[type="number"]::-webkit-inner-spin-button,input[type="number"]::-webkit-outer-spin-button{height:auto}input[type="search"]{-webkit-appearance:textfield;-moz-box-sizing:content-box;-webkit-box-sizing:content-box;box-sizing:content-box}input[type="search"]::-webkit-search-cancel-button,input[type="search"]::-webkit-search-decoration{-webkit-appearance:none}fieldset{border:1px solid #c0c0c0;margin:0 2px;padding:.35em .625em .75em}legend{border:0;padding:0}textarea{overflow:auto}optgroup{font-weight:bold}table{border-collapse:collapse;border-spacing:0}td,th{padding:0}
/*
<!-- Constants -->
<Variable name="damionRegular36" description="Damion Regular 36" type="font" default="400 36px Damion, cursive" hideEditor="true"  value="400 36px Damion, cursive"/>
<Variable name="playfairDisplayBlack28" description="Playfair Display Black 28" type="font" default="900 28px Playfair Display, serif" hideEditor="true"  value="900 28px Playfair Display, serif"/>
<Variable name="robotoNormal15" description="Roboto Normal 15" type="font" default="15px Roboto, sans-serif" hideEditor="true"  value="15px Roboto, sans-serif"/>
<Variable name="robotoNormal16" description="Roboto Normal 16" type="font" default="16px Roboto, sans-serif" hideEditor="true"  value="16px Roboto, sans-serif"/>
<Variable name="robotoBold22" description="Roboto Bold 22" type="font" default="bold 22px Roboto, sans-serif" hideEditor="true"  value="bold 22px Roboto, sans-serif"/>
<Variable name="robotoBold30" description="Roboto Bold 30" type="font" default="bold 30px Roboto, sans-serif" hideEditor="true"  value="bold 30px Roboto, sans-serif"/>
<Variable name="robotoBold45" description="Roboto Bold 45" type="font" default="bold 45px Roboto, sans-serif" hideEditor="true"  value="bold 45px Roboto, sans-serif"/>

<Variable name="keycolor" description="Main Color" type="color" default="#2196f3" value="#2196f3"/>
<Variable name="startSide" description="Start side in blog language" type="automatic" default="left" hideEditor="true"/>
<Variable name="endSide" description="End side in blog language" type="automatic" default="right" hideEditor="true"/>

<Group description="Page Text">
  <Variable name="body.text.font" description="Font" type="font" default="$(robotoNormal15)" value="15px Roboto, sans-serif"/>
  <Variable name="body.text.color" description="Color" type="color" default="#757575" value="#757575"/>
</Group>
<Group description="Backgrounds">
  <Variable name="body.background.height" description="Background height" type="length" min="420px" max="640px" default="480px" value="480px"/>
  <Variable name="body.background" description="Background" color="$(body.background.color)" type="background" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
  <Variable name="body.background.color" description="Body background color" type="color" default="#eee" value="#eeeeee"/>
  <Variable name="posts.background.color" description="Post background color" type="color" default="#fff" value="#ffffff"/>
  <Variable name="body.background.blur" description="Background blur" type="length" min="0px" max="50px" default="0px" value="0px"/>
</Group>
<Group description="Links">
  <Variable name="body.link.color" description="Link color" type="color" default="#2196f3" value="#2196f3"/>
  <Variable name="body.link.visited.color" description="Visited link color" type="color" default="$(body.link.color)" value="#2196f3"/>
  <Variable name="body.link.hover.color" description="Link Hover Color" type="color" default="$(body.link.color)" value="#2196f3"/>
</Group>
<Group description="Blog title" selector="div.widget.Header">
  <Variable name="blog.title.font" description="Font" type="font" default="$(robotoBold45)" value="bold 45px Roboto, sans-serif"/>
  <Variable name="blog.title.color" description="Color" type="color" default="#fff" value="#ffffff"/>
  <Variable name="header.icons.color" description="Background icons color" type="color" default="#fff" value="#ffffff"/>
</Group>
<Group description="Tabs text" selector="div.widget.PageList">
  <Variable name="tabs.font" description="Font" type="font" family="$(robotoNormal15.family)" size="$(robotoNormal15.size)" default="700 normal $(size) $(family)" value="700 normal $(size) $(family)"/>
  <Variable name="tabs.color" description="Text color" type="color" default="#ccc" value="#cccccc"/>
  <Variable name="tabs.selected.color" description="Selected color" type="color" default="#fff" value="#ffffff"/>
  <Variable name="tabs.overflow.background.color" description="Popup background color" type="color" default="$(posts.background.color)" value="#ffffff"/>
  <Variable name="tabs.overflow.color" description="Popup text color" type="color" default="$(posts.text.color)" value="#757575"/>
  <Variable name="tabs.overflow.selected.color" description="Popup selected color" type="color" default="$(posts.title.color)" value="#212121"/>
</Group>
<Group description="Posts" selector="div.widget.Blog">
  <Variable name="posts.title.color" description="Post title color" type="color" default="#212121" value="#212121"/>
  <Variable name="posts.title.font" description="Post title font" type="font" default="$(robotoBold22)" value="bold 24px Roboto, sans-serif"/>
  <Variable name="posts.stream.title.font" description="Post title stream font" type="font" default="$(robotoBold30)" value="bold 24px Roboto, sans-serif"/>
  <Variable name="posts.text.font" description="Post text font" type="font" default="$(body.text.font)" value="15px Roboto, sans-serif"/>
  <Variable name="posts.text.color" description="Post text color" type="color" default="$(body.text.color)" value="#757575"/>
  <Variable name="posts.byline.color" description="Post byline color" type="color" default="rgba(0, 0, 0, 0.54)" value="#000000"/>
  <Variable name="blockquote.font" description="Blockquote font" type="font" default="italic 300 15px Roboto, sans-serif" value="italic 300 15px Roboto, sans-serif"/>
  <Variable name="blockquote.color" description="Blockquote color" type="color" default="#444" value="#444444"/>
  <Variable name="posts.icons.color" description="Post icons color" type="color" default="#707070" value="#707070"/>
</Group>
<Group description="Search">
  <Variable name="search.input.color" description="Input color" type="color" default="$(blog.title.color)" value="#ffffff"/>
  <Variable name="search.input.font" description="Input font" type="font" default="$(robotoNormal16)" value="16px Roboto, sans-serif"/>
  <Variable name="search.placeholder.color" description="Placeholder text color" type="color" default="$(blog.title.color)" value="#ffffff"/>
</Group>
<Group description="Sharing">
  <Variable name="sharing.background.color" description="Sharing background color" type="color" default="$(posts.background.color)" value="#ffffff"/>
  <Variable name="sharing.text.color" description="Sharing text color" type="color" default="$(posts.title.color)" value="#212121"/>
  <Variable name="sharing.icons.color" description="Sharing icons color" type="color" default="$(sharing.text.color)" value="#212121"/>
</Group>
<Group description="Popular posts" selector="div.widget.PopularPosts">
  <Variable name="popularposts.background.color" description="Popular post background color" type="color" default="$(body.background.color)" value="#eeeeee"/>
  <Variable name="popularposts.byline.color" description="Popular post byline color" type="color" default="$(posts.byline.color)" value="#000000"/>
  <Variable name="popularposts.title.color" description="Popular post title color" type="color" default="$(posts.title.color)" value="#212121"/>
  <Variable name="popularposts.text.color" description="Popular post text color" type="color" default="$(posts.text.color)" value="#757575"/>
  <Variable name="popularposts.link.color" description="Popular post link color" type="color" default="$(body.link.color)" value="#2196f3"/>
</Group>
<Group description="Post navigation" selector='div.blog-pager'>
  <Variable name="posts.navigation.link.color" description="Post navigation links color" type="color" default="$(body.link.color)" value="#2196f3"/>
  <Variable name="posts.navigation.link.visited.color" description="Post navigation links visited color" type="color" default="$(body.link.visited.color)" value="#2196f3"/>
  <Variable name="posts.navigation.link.hover.color" description="Post navigations links hover color" type="color" default="$(body.link.hover.color)" value="#2196f3"/>
</Group>
<Group description="Sidebar" selector="div.sidebar-container">
  <Variable name="sidebar.backgroundColorTop" description="Background color (Top)" type="color" default="#f7f7f7" value="#ffffff"/>
  <Variable name="sidebar.backgroundColorTopHD" description="Background color (Top) - HD" type="color" default="rgba(255, 255, 255, 1)" value="#f7f7f7"/>
  <Variable name="sidebar.backgroundColorBottom" description="Background color (Bottom)" type="color" default="#fff" value="#ffffff"/>
  <Variable name="sidebar.separator.color" description="Separator color" type="color" default="#ccc" value="#cccccc"/>
  <Variable name="widget.title.color" description="Gadget title color" type="color" default="#212121" value="#212121"/>
  <Variable name="sidebar.icons.color" description="Sidebar icons color" type="color" default="#707070" value="#707070"/>
</Group>
<Group description="Labels" selector=".widget.Label">
  <Variable name="labels.text.color" description="Label text color" type="color" default="$(body.link.color)" value="#000000"/>
  <Variable name="labels.background.color" description="Label background color" type="color" red="$(labels.text.color.red)" green="$(labels.text.color.green)" blue="$(labels.text.color.blue)" default="rgba($red, $green, $blue, 0.05)" value="#f7f7f7"/>
</Group>
<Group description="Attribution" selector=".widget.Attribution">
  <Variable name="attribution.text.color" description="Attribution text color" type="color" default="$(body.text.color)" value="#757575"/>
  <Variable name="attribution.link.color" description="Attribution link color" type="color" default="$(body.link.color)" value="#2196f3"/>
  <Variable name="attribution.icon.color" description="Attribution icon color" type="color" default="#707070" hideEditor="true" value="#707070"/>
</Group>
<Group description="Widths">
  <Variable name="sidebar.width" description="Sidebar width" type="length" min="100px" max="1000px" default="284px" value="284px"/>
  <Variable name="content.width" description="Content width" type="length" min="600px" max="2400px" default="922px" value="922px"/>
  <Variable name="content.margin" description="Content margin" type="length" min="0px" max="1000px" default="117px" value="117px"/>
</Group>
 */

/*!************************************************
 * Blogger Template Style — English LTR
 **************************************************/
body{overflow-wrap:break-word;word-break:break-word;word-wrap:break-word}
.hidden{display:none}
.invisible{visibility:hidden}
.container::after,.float-container::after{clear:both;content:"";display:table}
.clearboth{clear:both}
#comments .comment .comment-actions,.widget.Profile .profile-link,.widget.Profile .profile-link.visit-profile{background:0 0;border:0;box-shadow:none;color:$(body.link.color);cursor:pointer;font-size:14px;font-weight:700;outline:0;text-decoration:none;text-transform:uppercase;width:auto}
.dim-overlay{background-color:rgba(0,0,0,.54);height:100vh;left:0;position:fixed;top:0;width:100%}
input::-ms-clear{display:none}
.loading-spinner-large{-webkit-animation:mspin-rotate 1.568s infinite linear;animation:mspin-rotate 1.568s infinite linear;height:48px;overflow:hidden;position:absolute;width:48px;z-index:200}
@-webkit-keyframes mspin-rotate{from{-webkit-transform:rotate(0);transform:rotate(0)}to{-webkit-transform:rotate(360deg);transform:rotate(360deg)}}
@keyframes mspin-rotate{from{-webkit-transform:rotate(0);transform:rotate(0)}to{-webkit-transform:rotate(360deg);transform:rotate(360deg)}}
.skip-navigation{background-color:#fff;box-sizing:border-box;color:#000;display:block;height:0;left:0;line-height:50px;overflow:hidden;padding-top:0;position:fixed;text-align:center;top:0;-webkit-transition:box-shadow .3s,height .3s,padding-top .3s;transition:box-shadow .3s,height .3s,padding-top .3s;width:100%;z-index:900}
.skip-navigation:focus{box-shadow:0 4px 5px 0 rgba(0,0,0,.14),0 1px 10px 0 rgba(0,0,0,.12),0 2px 4px -1px rgba(0,0,0,.2);height:50px}
#main{outline:0}
.main-heading{position:absolute;clip:rect(1px,1px,1px,1px);padding:0;border:0;height:1px;width:1px;overflow:hidden}
.Attribution{margin-top:1em;text-align:center}
.Attribution div{line-height:24px;margin-top:.5em}
.Attribution .copyright,.Attribution .image-attribution{font-size:.7em;margin-top:1.5em}
.post-body img{max-width:100%}
.post-body iframe{max-width:100%}
.post-body a[imageanchor="1"]{display:inline-block}
.byline{margin-right:1em}
.byline:last-child{margin-right:0}
.item-control{display:none}
#comments{border-top:1px dashed rgba(0,0,0,.54);margin-top:20px;padding:20px}
#comments .comment-thread ol{margin:0;padding-left:0}
#comments .comment .comment-replybox-single,#comments .comment-thread .comment-replies{margin-left:60px}
#comments .comment-thread .thread-count{display:none}
#comments .comment{list-style-type:none;padding:0 0 30px;position:relative}
#comments .comment .comment{padding-bottom:8px}
.comment .avatar-image-container{position:absolute}
.comment .avatar-image-container img{border-radius:50%}
.avatar-image-container svg,.comment .avatar-image-container .avatar-icon{border-radius:50%;border:solid 1px $(posts.icons.color);box-sizing:border-box;fill:$(posts.icons.color);height:35px;margin:0;padding:7px;width:35px}
.comment .comment-block{margin-top:10px;margin-left:60px;padding-bottom:0}
#comments .comment-author-header-wrapper{margin-left:40px}
#comments .comment .comment-header .user,#comments .comment .comment-header .user a{color:$(posts.title.color);font-style:normal;font-weight:700}
#comments .comment .comment-actions{bottom:0;margin-bottom:15px;position:absolute}
#comments .comment .comment-actions>*{margin-right:8px}
#comments .comment .comment-header .datetime{bottom:0;color:rgba($(posts.title.color.red),$(posts.title.color.green),$(posts.title.color.blue),.54);display:inline-block;font-size:13px;font-style:italic;margin-left:8px}
#comments .comment .comment-content,.comment .comment-body{margin-top:12px;word-break:break-word}
.comment-body{margin-bottom:12px}
.extendable .remaining-items{height:0;overflow:hidden;-webkit-transition:height .3s cubic-bezier(.4,0,.2,1);transition:height .3s cubic-bezier(.4,0,.2,1)}
.extendable .remaining-items.expanded{height:auto}
.svg-icon-24,.svg-icon-24-button{cursor:pointer;height:24px;width:24px;min-width:24px}
.touch-icon{margin:-12px;padding:12px}
.collapsible{-webkit-transition:height .3s cubic-bezier(.4,0,.2,1);transition:height .3s cubic-bezier(.4,0,.2,1)}
.collapsible,.collapsible>summary{display:block;overflow:hidden}
.collapsible>:not(summary){display:none}
.collapsible[open]>:not(summary){display:block}
.collapsible>summary{cursor:pointer;display:block;padding:0}
.collapsible>summary::-webkit-details-marker{display:none}
.collapsible-title{-webkit-box-align:center;align-items:center;display:flex}
.collapsible-title .title{flex:1 1 auto;order:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.collapsible-title .chevron-down,.collapsible[open] .collapsible-title .chevron-up{display:block}
.collapsible-title .chevron-up,.collapsible[open] .collapsible-title .chevron-down{display:none}
.flat-button{cursor:pointer;display:inline-block;font-weight:700;text-transform:uppercase;border-radius:2px;padding:8px;margin:-8px}
.flat-icon-button{background:0 0;border:0;margin:0;outline:0;padding:0;margin:-12px;padding:12px;cursor:pointer;box-sizing:content-box;display:inline-block;line-height:0}
.flat-icon-button,.flat-icon-button .splash-wrapper{border-radius:50%}
.pill-button{background:0 0;border:1px solid;border-radius:12px;cursor:pointer;display:inline-block;padding:4px 16px;text-transform:uppercase}
.ripple{position:relative}
.splash-wrapper{bottom:0;left:0;overflow:hidden;pointer-events:none;position:absolute;right:0;top:0;z-index:0}
.splash{background:#ccc;border-radius:100%;display:block;opacity:.6;position:absolute;-webkit-transform:scale(0);transform:scale(0)}
.splash.animate{-webkit-animation:ripple-effect .4s linear;animation:ripple-effect .4s linear}
@-webkit-keyframes ripple-effect{100%{opacity:0;-webkit-transform:scale(2.5);transform:scale(2.5)}}
@keyframes ripple-effect{100%{opacity:0;-webkit-transform:scale(2.5);transform:scale(2.5)}}
.search{display:flex;line-height:24px;width:24px}
.search.focused{width:100%}
.search form{z-index:101}
.search h3{display:none}
.search form{display:flex;flex:1 0 0;border-bottom:solid 1px transparent;padding-bottom:8px}
.search form>*{display:none}
.search.focused form>*{display:block}
.search .search-input label{display:none}
.search.focused form{border-color:$(blog.title.color);position:relative;width:auto}
.search-expand{flex:0 0 auto}
.search-expand-text{display:none}
.search-close{display:inline;vertical-align:middle}
.search-input{flex:1 0 1px}
.search-input input{background:0 0;border:0;box-sizing:border-box;color:$(blog.title.color);display:inline-block;outline:0;width:calc(100% - 48px)}
.search-focused>*{visibility:hidden}
.search-focused .search,.search-focused .search-icon{visibility:visible}
.search.focused .search-action{display:block}
.search.focused .search-action:disabled{opacity:.3}
.post-share-buttons{position:relative}
.share-buttons{background-color:$(sharing.background.color);border-radius:2px;box-shadow:0 2px 2px 0 rgba(0,0,0,.14),0 3px 1px -2px rgba(0,0,0,.2),0 1px 5px 0 rgba(0,0,0,.12);color:$(sharing.text.color);list-style:none;margin:0;padding:8px 0;position:absolute;top:-11px;min-width:200px;z-index:101}
.share-buttons.hidden{display:none}
.sharing-button{background:0 0;border:0;margin:0;outline:0;padding:0;cursor:pointer}
.share-buttons li{margin:0;height:48px}
.share-buttons li .sharing-platform-button{box-sizing:border-box;cursor:pointer;display:block;height:100%;margin-bottom:0;padding:0 16px;position:relative;width:100%}
.share-buttons li .platform-sharing-text{display:block;font-size:16px;line-height:48px;white-space:nowrap;margin-left:56px}
.sidebar-container{background-color:$(sidebar.backgroundColorBottom);max-width:$(sidebar.width);overflow-y:auto;-webkit-transition-property:-webkit-transform;transition-property:transform;-webkit-transition-duration:.3s;transition-duration:.3s;width:$(sidebar.width);z-index:101;-webkit-overflow-scrolling:touch}
.sidebar-container .navigation{line-height:0;padding:16px}
.sidebar-container .sidebar-back{cursor:pointer}
.sidebar-container .widget{background:0 0;margin:0 16px;padding:16px 0}
.sidebar-container .widget .title{color:$(widget.title.color);margin:0}
.sidebar-container .widget ul{list-style:none;margin:0;padding:0}
.sidebar-container .widget li{font-size:16px;line-height:normal}
.sidebar-container .widget+.widget{border-top:1px dashed $(sidebar.separator.color)}
.BlogArchive li{margin:16px 0}
.BlogArchive li:last-child{margin-bottom:0}
.Label li a{display:inline-block}
.BlogArchive .post-count,.Label .label-count{float:right;margin-left:.25em}
.BlogArchive .post-count::before,.Label .label-count::before{content:"("}
.BlogArchive .post-count::after,.Label .label-count::after{content:")"}
.dim-overlay{background-color:rgba(0,0,0,.54);z-index:100}
body.sidebar-visible{overflow-y:hidden}
@media screen and (max-width:$(sidebar.width + content.width + content.margin * 2 - 1px)){
.sidebar-container{bottom:0;position:fixed;top:0;left:0;right:auto}
.sidebar-container.sidebar-invisible{-webkit-transition-timing-function:cubic-bezier(.4,0,.6,1);transition-timing-function:cubic-bezier(.4,0,.6,1);-webkit-transform:translateX($(sidebar.width * -1));-ms-transform:translateX($(sidebar.width * -1));transform:translateX($(sidebar.width * -1))}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
.sidebar-container{position:absolute;top:0;left:0;right:auto}
.sidebar-container .navigation{display:none}
}
.sidebar-container,.sidebar-container .sidebar_bottom{background-color:$(sidebar.backgroundColorBottom)}
.sidebar-container .navigation,.sidebar-container .sidebar_top_wrapper{background-color:$(sidebar.backgroundColorTop)}
.sidebar-container .sidebar_top{overflow:auto}
.sidebar-container .sidebar_bottom{width:100%;padding-top:16px}
.sidebar-container .widget:first-child{padding-top:0}
.widget.Profile{margin:0;width:100%}
.widget.Profile h2{display:none}
.widget.Profile .individual{text-align:center}
.widget.Profile .profile-img{border-radius:50%;float:none}
.widget.Profile .profile-link{color:$(posts.title.color);font-size:.9em;margin-bottom:1em;opacity:.87;overflow:hidden;display:flex}
body.sidebar-visible .page_body{overflow-y:scroll}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
.sidebar-container{margin-top:$(body.background.height);min-height:calc(100% - $(body.background.height));overflow:visible;z-index:32}
.sidebar-container .sidebar_top_wrapper{background-color:$(sidebar.backgroundColorTopHD);height:$(body.background.height);margin-top:$(body.background.height * -1)}
.sidebar-container .sidebar_top{display:flex;height:$(body.background.height);flex-direction:row;max-height:$(body.background.height)}
.sidebar-container .sidebar_bottom{max-width:$(sidebar.width);width:$(sidebar.width)}
body.collapsed-header .sidebar-container{z-index:15}
.sidebar-container .sidebar_top:empty{display:none}
.sidebar_top_wrapper.no-items{display:none}
}
.post-snippet.snippet-container{max-height:120px}
.post-snippet .snippet-item{line-height:24px}
.post-snippet .snippet-fade{background:linear-gradient(to left,$(posts.background.color) 0,$(posts.background.color) 20%,$(posts.background.color.transparent) 100%);color:$(body.text.color);height:24px}
.popular-posts-snippet.snippet-container{max-height:72px}
.popular-posts-snippet .snippet-item{line-height:24px}
.post-bottom{align-items:center;display:flex;flex-wrap:wrap}
.post-footer{flex:1 1 auto;flex-wrap:wrap;order:1}
.post-footer>*{flex:0 1 auto}
.post-footer .byline:last-child{margin-right:1em}
.jump-link{flex:0 0 auto;order:2}
.centered-top-container.sticky{left:0;position:fixed;right:0;top:0;width:auto;z-index:50;transition-property:opacity,transform;transition-duration:.2s;transition-timing-function:cubic-bezier(.4,0,.2,1)}
.centered-top-placeholder{display:none}
.collapsed-header .centered-top-placeholder{display:block}
.centered-top-container img,.centered-top-placeholder img{max-width:100%}
body{background-color:$(body.background.color);color:$(body.text.color);font:$(body.text.font);margin:0;min-height:100vh}
img{max-width:100%}
h3{color:$(body.text.color);font-size:16px}
a{text-decoration:none;color:$(body.link.color)}
a:visited{color:$(body.link.visited.color)}
a:hover{color:$(body.link.hover.color)}
blockquote{color:$(blockquote.color);font:$(blockquote.font);font-size:x-large;text-align:center}
.pill-button{font-size:12px}
.bg-photo-container{height:$(body.background.height);overflow:hidden;position:absolute;width:100%;z-index:1}
.bg-photo{background:$(body.background);background-attachment:scroll;background-size:cover;-webkit-filter:blur($(body.background.blur));filter:blur($(body.background.blur));height:calc(100% + 2 * $(body.background.blur));left:$(0 - body.background.blur);position:absolute;top:$(0 - body.background.blur);width:calc(100% + 2 * $(body.background.blur))}
.bg-photo-overlay{background:rgba(0,0,0,.26);background-size:cover;height:$(body.background.height);position:absolute;width:100%;z-index:2}
.hamburger-menu{float:left;margin-top:0}
.search{border-bottom:solid 1px $(blog.title.color.transparent);float:right;position:relative;transition-property:width;transition-duration:.5s;transition-timing-function:cubic-bezier(.4,0,.2,1);z-index:101}
.search .dim-overlay{background-color:transparent}
.search form{height:36px;transition-property:border-color;transition-delay:.5s;transition-duration:.2s;transition-timing-function:cubic-bezier(.4,0,.2,1)}
.search.focused{width:calc(100% - 48px)}
.search.focused form{display:flex;flex:1 0 1px;border-color:$(blog.title.color);margin-left:-24px;padding-left:36px;position:relative;width:auto}
.item-view .search,.sticky .search{right:0;float:none;margin-left:0;position:absolute}
.item-view .search.focused,.sticky .search.focused{width:calc(100% - 50px)}
.item-view .search.focused form,.sticky .search.focused form{border-bottom-color:$(posts.text.color)}
.search_button{flex:0 0 24px;flex-direction:column}
.search-input{height:48px}
.search-input input{display:block;color:$(search.input.color);font:$(search.input.font);height:48px;line-height:48px;padding:0;width:100%}
.search-input input::placeholder{color:$(search.placeholder.color);opacity:.3}
.search-action{background:0 0;border:0;color:$(blog.title.color);cursor:pointer;display:none;height:48px;margin-top:0}
.sticky .search-action{color:$(posts.text.color)}
.page_body{position:relative;z-index:20}
.page_body .widget{margin-bottom:16px}
.page_body .centered{box-sizing:border-box;display:flex;flex-direction:column;margin:0 auto;max-width:$(content.width);min-height:100vh;padding:24px 0}
.page_body .centered>*{flex:0 0 auto}
.page_body .centered>#footer{margin-top:auto}
.blog-name{margin:24px 0 16px 0}
.item-view .blog-name,.sticky .blog-name{box-sizing:border-box;margin-left:36px;min-height:48px;opacity:1;padding-top:12px}
.blog-name .PageList{margin-top:16px;padding-top:8px;text-align:center}
.blog-name .PageList .overflowable-contents{width:100%}
.blog-name .PageList h3.title{color:$(blog.title.color);margin:8px auto;text-align:center;width:100%}
.item-view .return_link{margin-bottom:12px;margin-top:12px;position:absolute}
.item-view .blog-name{display:flex;flex-direction:column;flex-wrap:wrap;margin:0 48px 27px 48px}
.item-view #header,.item-view .Header{margin-bottom:5px}
.item-view .sticky .Header{margin-bottom:0}
.item-view .Header p{margin:10px 0 0 0;text-align:center}
.sticky{background:$(posts.background.color);box-shadow:0 0 20px 0 rgba(0,0,0,.7);box-sizing:border-box;margin-left:0}
.sticky #header{margin-bottom:8px;margin-right:8px}
.sticky .centered-top{margin:4px auto;max-width:$(content.width - 32px);min-height:48px}
.sticky .blog-name{display:flex;margin:0 48px}
.sticky .blog-name #header{flex:0 1 auto;order:1;overflow:hidden}
.sticky .Header h1{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-right:-10px;margin-bottom:-10px;padding-right:10px;padding-bottom:10px}
.sticky .Header p{display:none}
.sticky .PageList{display:none}
.search-focused>*{visibility:visible}
.search-focused .hamburger-menu{visibility:visible}
.item-view .search-focused .blog-name,.sticky .search-focused .blog-name{opacity:0}
.centered-bottom,.centered-top-container,.centered-top-placeholder{padding:0 16px}
.centered-top{position:relative}
.Header h1{color:$(blog.title.color);font:$(blog.title.font);line-height:normal;margin:0 0 13px 0;text-align:center;width:100%}
.Header h1 a,.Header h1 a:hover,.Header h1 a:visited{color:$(blog.title.color)}
.item-view .Header h1,.sticky .Header h1{font-size:24px;line-height:24px;margin:0;text-align:center}
.sticky .Header h1{color:$(posts.text.color)}
.sticky .Header h1 a,.sticky .Header h1 a:hover,.sticky .Header h1 a:visited{color:$(posts.text.color)}
.Header p{color:$(blog.title.color);margin:0 0 13px 0;opacity:.8;text-align:center}
.widget .title{line-height:28px}
.BlogArchive li{font-size:16px}
.BlogArchive .post-count{color:$(posts.text.color)}
#page_body .FeaturedPost,.Blog .blog-posts .post-outer-container{background:$(posts.background.color);min-height:40px;padding:30px 40px;width:auto}
.Blog .blog-posts .post-outer-container:last-child{margin-bottom:0}
.Blog .blog-posts .post-outer-container .post-outer{border:0;position:relative;padding-bottom:.25em}
.post-outer-container{margin-bottom:16px}
.post:first-child{margin-top:0}
.post-share-buttons-bottom,.post-share-buttons-top{float:right}
.post-share-buttons-bottom{margin-right:24px}
.post-footer,.post-header{clear:left;color:$(posts.byline.color);margin:0;width:inherit}
.blog-pager{text-align:center}
.blog-pager a{color:$(posts.navigation.link.color)}
.blog-pager a:visited{color:$(posts.navigation.link.visited.color)}
.blog-pager a:hover{color:$(posts.navigation.link.hover.color)}
.post-title{font:$(posts.title.font);float:left;margin:0 0 8px 0;max-width:calc(100% - 48px)}
.post-title a{font:$(posts.stream.title.font)}
.post-title,.post-title a,.post-title a:hover,.post-title a:visited{color:$(posts.title.color)}
.post-body{color:$(posts.text.color);font:$(posts.text.font);line-height:1.6em;margin:1.5em 0 2em 0;display:block}
.post-body img{height:inherit}
.post-body .snippet-thumbnail{float:left;margin:0;margin-right:2em;max-height:128px;max-width:128px}
.post-body .snippet-thumbnail img{max-width:100%}
.byline{color:$(posts.byline.color);display:inline-block;line-height:24px;margin-top:8px;vertical-align:top}
.byline.post-author:first-child{margin-right:0}
.byline.post-share-buttons{position:relative;display:inline-block;margin-top:0;width:100%}
.byline.post-share-buttons .sharing{float:right}
.flat-button.ripple:hover{background-color:rgba($(body.link.color.red),$(body.link.color.green),$(body.link.color.blue),.12)}
a.timestamp-link,a:active.timestamp-link,a:visited.timestamp-link{color:inherit;font:inherit;text-decoration:inherit}
.comment-link{color:$(body.link.color);position:relative}
.comment-link .num_comments{margin-left:8px;vertical-align:top}
.post-filter-message{background-color:rgba(0,0,0,.7);color:#fff;display:table;margin-bottom:16px;width:100%}
.post-filter-message div{display:table-cell;padding:15px 28px}
#blog-pager{margin:2em 0}
#blog-pager a{color:$(attribution.link.color);font-size:14px}
.tabs{list-style:none;margin:0 auto;padding:0}
.tabs li{display:inline-block;margin:0 8px;vertical-align:top}
.tabs li a{cursor:pointer;display:inline-block;font-weight:700;text-transform:uppercase;padding:12px 8px;color:$(tabs.color);font:$(tabs.font);line-height:$(body.text.font.size * 1.2)}
.tabs .selected{border-bottom:4px solid $(tabs.selected.color)}
.tabs .selected a{color:$(tabs.selected.color)}
.Label li,.Label span.label-size,.byline.post-labels a{background-color:$(labels.background.color);border:1px solid $(labels.background.color);border-radius:15px;display:inline-block;margin:4px 4px 4px 0;padding:3px 8px}
.Label a,.byline.post-labels a{color:$(labels.text.color)}
.Label ul{list-style:none;padding:0}
.PopularPosts{background-color:$(popularposts.background.color);padding:30px 40px}
.PopularPosts .item-content{color:$(popularposts.text.color);margin-top:24px}
.PopularPosts a,.PopularPosts a:hover,.PopularPosts a:visited{color:$(popularposts.link.color)}
.PopularPosts .post-title,.PopularPosts .post-title a,.PopularPosts .post-title a:hover,.PopularPosts .post-title a:visited{color:$(popularposts.title.color);font-size:18px;font-weight:700;line-height:24px}
.PopularPosts,.PopularPosts h3.title a{color:$(posts.text.color);font:$(posts.text.font)}
.main .PopularPosts{padding:16px 40px}
.PopularPosts h3.title{font-size:14px;margin:0}
.PopularPosts h3.post-title{margin-bottom:0}
.PopularPosts .byline{color:$(popularposts.byline.color)}
.PopularPosts .jump-link{float:right;margin-top:16px}
.PopularPosts ul{list-style:none;padding:0;margin:0}
.PopularPosts .post{padding:20px 0}
.PopularPosts .post+.post{border-top:1px dashed $(sidebar.separator.color)}
.PopularPosts .item-thumbnail{float:left;margin-right:32px}
.PopularPosts .item-thumbnail img{height:88px;padding:0;width:88px}
.inline-ad{margin-bottom:16px;display:none;max-width:100%;overflow:hidden}
.adsbygoogle{display:block;overflow:hidden}
.Attribution{color:$(attribution.text.color)}
.Attribution a,.Attribution a:hover,.Attribution a:visited{color:$(attribution.link.color)}
.Attribution svg{fill:$(attribution.icon.color)}

/* Mobile */
@media screen and (max-width:800px){
.blog-name{margin-top:0}
body.item-view .blog-name{margin:0 48px}
.centered-bottom{padding:8px}
body.item-view .blog-name,body.page-view .blog-name{display:flex;flex-direction:column;align-items:center}
body.item-view .blog-name .widget.Header,body.page-view .blog-name .widget.Header{width:100%;margin:0 0 8px 0}
body.item-view .blog-name .widget.PageList,body.page-view .blog-name .widget.PageList{width:100%;margin:0}
body.item-view .centered-bottom{padding:0}
.page_body .centered{padding:10px 0}
body.item-view #header,body.item-view .widget.Header{margin-right:0}
body.collapsed-header .centered-top-container .blog-name{display:block}
body.collapsed-header .centered-top-container .widget.Header h1{text-align:center}
.widget.Header header{padding:0}
.widget.Header h1{font-size:$(blog.title.font.size * 24 / 45);line-height:$(blog.title.font.size * 24 / 45);margin-bottom:13px}
body.item-view .widget.Header h1{text-align:center}
body.item-view .widget.Header p{text-align:center}
.blog-name .widget.PageList{padding:0}
body.item-view .centered-top{margin-bottom:5px}
body.item-view .centered-top-container:not(.sticky) .Header h1{display:none}
body.item-view .centered-top-container:not(.sticky) .PageList{display:none}
.search-action,.search-input{margin-bottom:-8px}
.search form{margin-bottom:8px}
#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{padding:16px}
div.widget.Blog .blog-posts .post-outer-container{padding:16px}
div.widget.Blog .blog-posts .post-outer-container .post-outer{padding:0}
.post:first-child{margin:0}
.post-body .snippet-thumbnail{margin:3px 3px 3px 0;float:left}
.post-body .snippet-thumbnail img{height:120px;width:120px;max-height:120px;max-width:120px;object-fit:cover;border-radius:6px}
div.widget.PopularPosts div.item-thumbnail{margin:0 3vw 3vw 0}
div.widget.PopularPosts div.item-thumbnail img{height:20vw;width:20vw;max-height:88px;max-width:88px}
.post-title{line-height:1}
.post-title,.post-title a{font-size:20px}
#page_body.section div.widget.FeaturedPost h3 a{font-size:22px}
.mobile-ad .inline-ad{display:block}
div.post-filter-message div{padding:8px 16px}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{position:relative}
body.item-view .blog-name{margin-left:48px}
.page_body{margin-left:$(sidebar.width)}
.search{margin-left:0}
.search.focused{width:100%}
.sticky{padding-left:$(sidebar.width)}
.hamburger-menu{display:none}
body.collapsed-header .page_body .centered-top-container{padding-left:$(sidebar.width);padding-right:0;width:100%}
body.collapsed-header .centered-top-container .search.focused{width:100%}
body.collapsed-header .centered-top-container .blog-name{margin-left:0}
body.collapsed-header.item-view .centered-top-container .search.focused{width:calc(100% - 50px)}
body.collapsed-header.item-view .centered-top-container .blog-name{margin-left:40px}
}

/* Footer links */
.footer-links{
  display:flex;
  justify-content:center;
  gap:18px;
  padding:20px 0;
  font-size:14px;
  direction:ltr;
}
.footer-links a{text-decoration:none;color:#777}
.footer-links a:hover{color:#000}

body#layout .bg-photo,body#layout .bg-photo-overlay{display:none}
body#layout .page_body{padding:0;position:relative;top:0}
body#layout .page{display:inline-block;left:inherit;position:relative;vertical-align:top;width:540px}
body#layout .centered{max-width:954px}
body#layout .navigation{display:none}
body#layout .sidebar-container{display:inline-block;width:40%}
body#layout .hamburger-menu,body#layout .search{display:none}

head.b:template-skin:

body#layout .hidden, body#layout .invisible { display: inherit; }
body#layout .navigation { display: none; }
body#layout .page, body#layout .sidebar_top, body#layout .sidebar_bottom { display: inline-block; left: inherit; position: relative; vertical-align: top; }
body#layout .page { float: right; margin-left: 20px; width: 55%; }
body#layout .sidebar-container { float: right; width: 40%; }
body#layout .hamburger-menu { display: none; }
